class Solution {
public:
    vector<int> simulationResult(vector<int>& windows, vector<int>& queries) {
        unordered_set<int> seen;
        vector<int> res;
        for (int i = (int)queries.size() - 1; i >= 0; --i) {
            if (!seen.count(queries[i])) {
                seen.insert(queries[i]);
                res.push_back(queries[i]);
            }
        }
        for (int w : windows) {
            if (!seen.count(w)) {
                seen.insert(w);
                res.push_back(w);
            }
        }
        return res;
    }
};

class Solution {
    public int[] simulationResult(int[] windows, int[] queries) {
        Set<Integer> seen = new HashSet<>();
        List<Integer> list = new ArrayList<>();
        for (int i = queries.length - 1; i >= 0; --i) {
            if (!seen.contains(queries[i])) {
                seen.add(queries[i]);
                list.add(queries[i]);
            }
        }
        for (int w : windows) {
            if (!seen.contains(w)) {
                seen.add(w);
                list.add(w);
            }
        }
        int[] res = new int[list.size()];
        for (int i = 0; i < list.size(); ++i) {
            res[i] = list.get(i);
        }
        return res;
    }
}

